import * as React from "react";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import { CircleIcon } from "lucide-react";

import { cn } from "@/lib/utils";

/**
 * figma: RadioGroup (State = Default | Disabled | Invalid, Dir = LTR | RTL) and
 * Radio (Interaction x Data state, 10 combinations). Dot is 16x16, radius-full;
 * checked fills with `primary` and draws a `primary` border.
 */
function RadioGroup({ className, ...props }: React.ComponentProps<typeof RadioGroupPrimitive.Root>) {
  return (
    <RadioGroupPrimitive.Root
      data-slot="radio-group"
      className={cn("grid gap-3", className)}
      {...props}
    />
  );
}

function RadioGroupItem({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Item>) {
  return (
    <RadioGroupPrimitive.Item
      data-slot="radio-group-item"
      className={cn(
        "aspect-square size-4 shrink-0 rounded-full border border-input bg-background shadow-xs",
        "transition-[color,box-shadow] outline-none",
        "data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground",
        "focus-visible:border-ring focus-visible:ring-ring-subtle focus-visible:ring-[3px]",
        "aria-invalid:border-destructive aria-invalid:ring-ring-destructive aria-invalid:ring-[3px]",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    >
      <RadioGroupPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="relative flex items-center justify-center"
      >
        <CircleIcon className="absolute top-1/2 left-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 fill-current stroke-none" />
      </RadioGroupPrimitive.Indicator>
    </RadioGroupPrimitive.Item>
  );
}

/**
 * The library's docs refer to this part as `RadioItem` — e.g. the Field
 * "Choice card" recipe: "This works with RadioItem, Checkbox and Switch".
 */
const RadioItem = RadioGroupItem;

export { RadioGroup, RadioGroupItem, RadioItem };
